package com.agriconnect.logistics;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController class ShipmentController{private final JdbcClient db;private final String key;ShipmentController(JdbcClient d,@Value("${internal.api-key}")String k){db=d;key=k;}private long uid(){return Long.parseLong(SecurityContextHolder.getContext().getAuthentication().getName());}private String sel(){return"select id,order_id as \"orderId\",buyer_id as \"buyerId\",logistics_user_id as \"logisticsUserId\",pickup_address as \"pickupAddress\",delivery_address as \"deliveryAddress\",status,shipped_at as \"shippedAt\",delivered_at as \"deliveredAt\" from shipments";}private Map<String,Object>one(long id){return db.sql(sel()+" where id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"SHIPMENT_NOT_FOUND","Shipment not found"));}
@GetMapping("/api/shipments")Map<String,Object>all(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var a=SecurityContextHolder.getContext().getAuthentication();String role=a.getAuthorities().iterator().next().getAuthority();String where=switch(role){case"ROLE_ADMIN"->"";case"ROLE_LOGISTICS"->" where logistics_user_id=:u";case"ROLE_BUYER"->" where buyer_id=:u";default->" where position(','||:u||',' in ','||farmer_ids||',')>0";};var q=db.sql(sel()+where+" order by id desc limit :s offset :o").param("s",size).param("o",page*size);if(!where.isEmpty())q=q.param("u",uid());var rows=q.query().listOfRows();return Map.of("content",rows,"number",page,"size",size,"totalElements",rows.size(),"totalPages",rows.isEmpty()?0:1,"first",true,"last",true,"empty",rows.isEmpty());}
@GetMapping("/api/shipments/{id}")Map<String,Object>get(@PathVariable long id){return one(id);}@GetMapping("/api/shipments/order/{orderId}")Map<String,Object>byOrder(@PathVariable long orderId){return db.sql(sel()+" where order_id=:o").param("o",orderId).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"SHIPMENT_NOT_FOUND","Shipment not found"));}@GetMapping("/api/shipments/my")Map<String,Object>mine(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return all(page,size);}
@PatchMapping("/api/shipments/{id}/status")@PreAuthorize("hasAnyRole('LOGISTICS','ADMIN')")@Transactional Map<String,Object>status(@PathVariable long id,@RequestParam String status){Map<String,Object>s=one(id);String from=String.valueOf(s.get("status"));if(!valid(from,status))throw new DomainException(HttpStatus.CONFLICT,"INVALID_SHIPMENT_STATUS_TRANSITION","Invalid shipment status transition");db.sql("update shipments set status=:s,shipped_at=case when :s='SHIPPING' then coalesce(shipped_at,now()) else shipped_at end,delivered_at=case when :s='DELIVERED' then now() else delivered_at end where id=:id").param("s",status).param("id",id).update();db.sql("insert into shipment_status_history(shipment_id,from_status,to_status,changed_by)values(:id,:f,:t,:u)").param("id",id).param("f",from).param("t",status).param("u",uid()).update();return one(id);}
@PostMapping("/internal/shipments")Map<String,Object>create(@RequestHeader("X-Internal-Api-Key")String k,@RequestBody Map<String,Object>x){if(!java.security.MessageDigest.isEqual(k.getBytes(),key.getBytes()))throw new DomainException(HttpStatus.FORBIDDEN,"INVALID_INTERNAL_KEY","Invalid internal key");long order=((Number)x.get("orderId")).longValue();var old=db.sql(sel()+" where order_id=:o").param("o",order).query().listOfRows().stream().findFirst();if(old.isPresent())return old.get();var kh=new GeneratedKeyHolder();db.sql("insert into shipments(order_id,buyer_id,farmer_ids,logistics_user_id,pickup_address,delivery_address,status)values(:o,:b,:f,:l,:p,:d,'PENDING')").param("o",order).param("b",x.get("buyerId")).param("f",x.getOrDefault("farmerIds","")).param("l",x.get("logisticsUserId")).param("p",x.get("pickupAddress")).param("d",x.get("deliveryAddress")).update(kh,"id");return one(kh.getKey().longValue());}private boolean valid(String a,String b){return switch(a){case"PENDING"->Set.of("CONFIRMED","CANCELLED").contains(b);case"CONFIRMED"->Set.of("PACKING","CANCELLED").contains(b);case"PACKING"->b.equals("SHIPPING");case"SHIPPING"->b.equals("DELIVERED");default->false;};}}
